class En : IGreeter { public string Hi() => "hello"; }
class Fr : IGreeter { public string Hi() => "bonjour"; }

using Microsoft.Extensions.DependencyInjection.Extensions;

var services = new ServiceCollection();
services.AddSingleton<IStore, SqlStore>();
services.TryAddSingleton<IStore, MemStore>();
var store = services.BuildServiceProvider().GetRequiredService<IStore>();
Console.WriteLine($"{services.Count} {store.GetType().Name}");

interface IStore { }
class SqlStore : IStore { }
class MemStore : IStore { }

var log = new List<string>();
var app = new ApplicationBuilder(new ServiceCollection().BuildServiceProvider());
app.Use(async (ctx, next) => { log.Add("A1"); await next(ctx); log.Add("A2"); });
app.Use(async (ctx, next) => { log.Add("B1"); await next(ctx); log.Add("B2"); });
app.Run(ctx => { log.Add("C"); return Task.CompletedTask; });

await app.Build()(new DefaultHttpContext());
