var log = new List<string>();
var app = new ApplicationBuilder(new ServiceCollection().BuildServiceProvider());
app.Use(async (ctx, next) => { log.Add("A"); await next(ctx); });

var ctx = new DefaultHttpContext();
await app.Build()(ctx);
