var config = new ConfigurationBuilder()
    .AddInMemoryCollection(new Dictionary<string, string?>
        { ["Port"] = "80", ["Host"] = "a" })
    .AddInMemoryCollection(new Dictionary<string, string?>
        { ["Port"] = "8080" })
    .Build();
Console.WriteLine($"{config["Host"]}:{config["Port"]}");

var config = new ConfigurationBuilder()
    .AddInMemoryCollection(new Dictionary<string, string?> { ["Retries"] = "3" })
    .Build();
int a = config.GetValue<int>("Retries");
int b = config.GetValue<int>("Timeout");
int c = config.GetValue("Timeout", 30);
Console.WriteLine($"{a} {b} {c}");

var config = new ConfigurationBuilder()
    .AddInMemoryCollection(new Dictionary<string, string?>
        { ["Db:Host"] = "srv", ["Db:Port"] = "5432" })
    .Build();
var db = config.GetSection("db");
string parent = config["Db"] ?? "null";
