var config = new ConfigurationBuilder().AddInMemoryCollection(
    new Dictionary<string, string?> { ["Mail:Port"] = "2525" }).Build();
var sp = new ServiceCollection()
    .Configure<MailOptions>(config.GetSection("Mail"))
    .BuildServiceProvider();
var o = sp.GetRequiredService<IOptions<MailOptions>>().Value;
Console.WriteLine($"{o.Port} {o.UseSsl}");

class MailOptions { public int Port { get; set; } = 25; public bool UseSsl { get; set; } = true; }

