using var factory = LoggerFactory.Create(b => b
    .SetMinimumLevel(LogLevel.Warning)
    .AddFilter("Db", LogLevel.Debug)
    .AddConsole());
var app = factory.CreateLogger("App");
var db = factory.CreateLogger("Db.Query");
Console.WriteLine($"{app.IsEnabled(LogLevel.Information)} " +
    $"{db.IsEnabled(LogLevel.Debug)} {db.IsEnabled(LogLevel.Trace)}");

using var cts = new CancellationTokenSource();
var token = cts.Token;
token.Register(() => Console.Write("A"));
Console.Write(token.IsCancellationRequested ? "1" : "0");
cts.Cancel();
token.Register(() => Console.Write("B"));
Console.Write(token.IsCancellationRequested ? "1" : "0");

var builder = Host.CreateApplicationBuilder();
builder.Logging.ClearProviders();
builder.Services.AddHostedService<A>();
builder.Services.AddHostedService<B>();
using var host = builder.Build();
await host.StartAsync(); await host.StopAsync();

class A : Svc { } class B : Svc { }
class Svc : IHostedService {
    public Task StartAsync(CancellationToken _) { Console.Write(GetType().Name + "+"); return Task.CompletedTask; }
    public Task StopAsync(CancellationToken _) { Console.Write(GetType().Name + "-"); return Task.CompletedTask; }
}
